import Root from "./1Adding Interactivity/5UpdatingArrays"
import { NotShared, Shared } from "./1Adding Interactivity/5zCoreCocept"
import Sub from "./subReLearn"
import "./ReLearn.css"

export default function () {
  return (
    <>
    <Screen/>
    </>
  );
}

import { useState } from "react"
import { useImmer } from "use-immer"

const initialNum = [{val: 0},{val:0}]
export function Screen() {
  const [num, setNum] = useImmer(initialNum)
  const [otherNum, setOtherNum] = useImmer(initialNum)
  function change() {
    setNum(draft => {
      draft.forEach(e => {
        e.val = 10
      })
    })
  }
  function otherChange() {
    setOtherNum(draft => {
      draft.forEach(e => {
        e.val = 10
      })
    })
  }
  return (
    <>
    <Elem content={num} func={change}/>
    <Elem content={otherNum} func={otherChange}/>
    </>
  );
}

function Elem({content, func}) {
  return content.map(e => <>
  {e.val} <button onClick={func}>click</button> <br/>
  </>)
}


// http://localhost:3000
